import numpy as np, json, math
from collections import Counter
import matplotlib.pyplot as plt

pdb=open("AF-Q88PR0.pdb").read().splitlines()
seq=open("q88pr0.fasta").read().split("\n")[1]
co={}
for L in pdb:
    if L.startswith("ATOM"):
        n=int(L[22:26]); a=L[12:16].strip()
        if a in ("N","CA","C"): co.setdefault(n,{})[a]=np.array([float(L[30:38]),float(L[38:46]),float(L[46:54])])
pl={}
for L in pdb:
    if L.startswith("ATOM") and L[12:16].strip()=="CA": pl[int(L[22:26])]=float(L[60:66])
nres=len(seq)
def dihed(p0,p1,p2,p3):
    b0,b1,b2=p0-p1,p2-p1,p3-p2
    b1/=np.linalg.norm(b1)
    v=b0-np.dot(b0,b1)*b1; w=b2-np.dot(b2,b1)*b1
    return math.degrees(math.atan2(np.dot(np.cross(b1,v),w),np.dot(v,w)))
ss=["C"]*(nres+1)
for i in range(2,nres):
    try:
        phi=dihed(co[i-1]["C"],co[i]["N"],co[i]["CA"],co[i]["C"])
        psi=dihed(co[i]["N"],co[i]["CA"],co[i]["C"],co[i+1]["N"])
    except KeyError: continue
    if -100<phi<-30 and -80<psi<-5: ss[i]="H"
    elif -180<phi<-45 and (90<psi<=180 or -180<=psi<-170): ss[i]="E"
S="".join(ss[1:nres+1])
def runs(S,ch,minlen):
    out=[];s=None
    for i,c in enumerate(S,1):
        if c==ch and s is None: s=i
        if c!=ch and s is not None:
            if i-s>=minlen: out.append((s,i-1))
            s=None
    if s and nres-s+1>=minlen: out.append((s,nres))
    return out
hel=runs(S,"H",6); strand=runs(S,"E",3)
print("Helices (>=6 aa):",hel)
print("\nStrands (>=3 aa):",strand)

# Coiled-coil heuristic: long helix (>=21 aa) with heptad hydrophobic periodicity at a/d
hyd=set("AILMFVWYC")
print("\nCoiled-coil heptad screen on helices >=21 aa:")
cc=[]
for a,b in hel:
    if b-a+1<21: continue
    best=(0,None)
    for off in range(7):
        pos=[i for i in range(a,b+1) if (i-a+off)%7 in (0,3)]
        f=sum(seq[i-1] in hyd for i in pos)/len(pos)
        if f>best[0]: best=(f,off)
    print(f"  helix {a}-{b} len={b-a+1} best a/d hydrophobic fraction={best[0]:.2f} (frame {best[1]})")
    if best[0]>=0.75: cc.append((a,b,best[0]))
print("  -> coiled-coil candidates (a/d hydrophobicity >=0.75):",cc if cc else "none")

# Low complexity: Shannon entropy, window 20
w=20; ent=np.full(nres,np.nan)
for i in range(nres-w+1):
    c=Counter(seq[i:i+w]); p=np.array(list(c.values()))/w
    ent[i+w//2]=-(p*np.log2(p)).sum()
lc=[]
s=None
for i in range(nres):
    low = (not np.isnan(ent[i])) and ent[i]<3.0
    if low and s is None: s=i+1
    if not low and s is not None:
        if i-s+1>=8: lc.append((s,i))
        s=None
print(f"\nLow-complexity (Shannon entropy<3.0 bits in 20-aa window, >=8 aa): {lc if lc else 'none'}")
print(f"  min entropy = {np.nanmin(ent):.2f} bits at residue {int(np.nanargmin(ent))+1}; median = {np.nanmedian(ent):.2f}")

res=np.array([pl[i] for i in sorted(pl)])
doms=[("DUF1631 N\nPF07793",25,217,"#4C78A8"),("DUF1631 2nd\nPF26671",285,433,"#72B7B2"),
      ("DUF1631 3rd\nPF26672",465,578,"#F58518"),("DUF1631_C\nTudor PF26670",630,696,"#E45756")]
fig,ax=plt.subplots(2,1,figsize=(13,6.2),sharex=True,height_ratios=[1,2.2])
for nm,a,b,c in doms:
    ax[0].add_patch(plt.Rectangle((a,0.25),b-a,0.5,color=c))
    ax[0].text((a+b)/2,0.5,nm,ha="center",va="center",fontsize=8,color="white",weight="bold")
for a,b in lc: ax[0].add_patch(plt.Rectangle((a,0.05),b-a,0.12,color="k"))
ax[0].set_ylim(0,1); ax[0].set_yticks([]); ax[0].set_title("Q88PR0 / PP_0788 (719 aa): four tandem DUF1631-family domains; black bars = low-complexity",fontsize=10)
ax[1].plot(range(1,nres+1),res,lw=1,color="#333")
ax[1].axhline(70,ls="--",color="r",lw=.8); ax[1].axhline(50,ls=":",color="r",lw=.8)
for nm,a,b,c in doms: ax[1].axvspan(a,b,color=c,alpha=.18)
for a,b in [(1,24),(218,284),(434,464),(579,629),(697,719)]:
    ax[1].axvspan(a,b,color="grey",alpha=.12)
ax[1].set_ylabel("AlphaFold pLDDT"); ax[1].set_xlabel("residue")
ax[1].set_xlim(1,nres); ax[1].text(240,20,"linker 1\n(218-284)\nmean 58",fontsize=7,ha="center")
ax[1].text(604,20,"linker 3\n(579-629)\nmean 53",fontsize=7,ha="center")
plt.tight_layout(); plt.show()
